<template>
  <div class="app-container platform-exchanges">
    <p v-if="!embedded" class="hint">保留平台申请和来源版本，再转业务换货单。平台状态、转单结果与实际出入库分别跟踪。</p>
    <el-form inline size="small" @submit.native.prevent="search">
      <el-form-item label="单号"><el-input v-model.trim="query.number" clearable placeholder="平台换货 / 主子单号 / HH / SO" style="width:300px" @keyup.enter.native="search" /></el-form-item>
      <el-form-item v-if="!embedded" label="店铺"><el-select v-model="query.channelId" filterable clearable><el-option v-for="c in channels" :key="c.channel_id" :value="c.channel_id" :label="c.channel_name" /></el-select></el-form-item>
      <el-form-item label="转单状态"><el-select v-model="query.state" clearable><el-option v-for="(v,k) in conversionStates" :key="k" :value="k" :label="v" /></el-select></el-form-item>
      <el-form-item><el-button type="primary" @click="search">查询</el-button><el-button @click="reset">{{ embedded?'清除本类筛选':'重置' }}</el-button><el-button type="text" @click="more=!more">{{ more?'收起筛选':'更多筛选' }}</el-button></el-form-item>
      <template v-if="more"><el-form-item label="平台状态"><el-select v-model="query.platformStatus" clearable><el-option v-for="(v,k) in platforms" :key="k" :value="k" :label="v" /></el-select></el-form-item><el-form-item label="申请阶段"><el-select v-model="query.phase" clearable><el-option v-for="(v,k) in phases" :key="k" :value="k" :label="v" /></el-select></el-form-item><el-form-item label="来源状态"><el-select v-model="query.sourceState" clearable><el-option v-for="(v,k) in sourceStates" :key="k" :value="k" :label="v" /></el-select></el-form-item><el-form-item label="换货类型"><el-select v-model="query.speed" clearable><el-option label="普通换货" value="0" /><el-option label="极速换货" value="1" /></el-select></el-form-item><el-form-item v-if="!embedded" label="平台修改时间"><el-date-picker v-model="range" type="datetimerange" value-format="yyyy-MM-dd HH:mm:ss" range-separator="至" /></el-form-item></template>
    </el-form>
    <div class="toolbar"><span class="hint">共 {{ total }} 条平台申请；未关联原单的记录仍保留在此。</span><div><el-button v-hasPermi="['order:exchange:sync']" size="small" type="primary" @click="backfill">补拉换货</el-button><el-button v-hasPermi="['order:exchange:sync']" size="small" @click="tasks">同步任务</el-button><el-button size="small" @click="load">刷新列表</el-button></div></div>
    <el-table v-loading="loading" :data="rows" row-key="id" empty-text="暂无平台换货申请，可检查店铺接入或创建补拉任务">
      <el-table-column label="平台换货 / 原订单" min-width="260"><template slot-scope="s"><el-button v-hasPermi="['order:exchange:query']" type="text" @click="open(s.row.id)">{{ s.row.dispute_id }}</el-button><el-button v-clipboard:copy="s.row.dispute_id" type="text" icon="el-icon-document-copy" aria-label="复制平台换货单号" /><div class="hint">平台主单 {{ s.row.platform_tid || '待关联' }}</div><div class="hint">平台子单 {{ s.row.platform_oid || '未提供' }}</div></template></el-table-column>
      <el-table-column label="渠道 / 店铺" min-width="170"><template slot-scope="s">天猫 · {{ shop(s.row.channel_id) }}<div class="hint">渠道 ID {{ s.row.channel_id }}</div></template></el-table-column>
      <el-table-column label="平台申请商品" min-width="230"><template slot-scope="s"><div>{{ s.row.original_description || '原规格未提供' }}</div><div class="target">→ {{ s.row.target_description || '目标规格未提供' }}</div><strong>申请 {{ s.row.requested_quantity }} 件</strong><div class="hint">OMS 目标 SKU：{{ s.row.target_sku || '待业务审核确认' }}</div></template></el-table-column>
      <el-table-column label="申请类型" min-width="125"><template slot-scope="s"><div>{{ phases[s.row.source_phase] }}</div><el-tag size="mini" :type="Number(s.row.speed_exchange)===1?'warning':'info'">{{ s.row.speed_exchange==null?'类型待确认':Number(s.row.speed_exchange)===1?'极速换货':'普通换货' }}</el-tag></template></el-table-column>
      <el-table-column label="平台状态 / 时限" min-width="180"><template slot-scope="s">{{ platforms[s.row.platform_status] || s.row.platform_status || '待核对' }}<div class="hint">{{ deadline(s.row) }}</div></template></el-table-column>
      <el-table-column label="来源与转单" min-width="220"><template slot-scope="s"><el-tag size="small" :type="s.row.conversion_state==='FAILED'?'warning':s.row.conversion_state==='SUCCESS'?'success':'info'">{{ conversionStates[s.row.conversion_state] }}</el-tag><div class="hint">{{ sourceStates[s.row.source_state] }} · 版本 {{ s.row.version }}</div><div class="warning">{{ s.row.source_error || s.row.conversion_error }}</div><message-progress v-if="s.row.message" :message="s.row.message" type="EXCHANGE_CONVERT"/><div class="hint">最近同步 {{ s.row.last_sync }}</div></template></el-table-column>
      <el-table-column label="业务关联" min-width="220"><template slot-scope="s"><router-link v-if="s.row.business_exchange_id" :to="businessLink(s.row)">{{ s.row.exchange_sn }}</router-link><span v-else class="hint">尚未生成业务换货单</span><div class="hint">{{ states[s.row.business_state] }}</div><div class="hint">{{ s.row.order_sn || '原 SO 待关联' }}</div></template></el-table-column>
      <el-table-column label="操作" :width="embedded?230:150" fixed="right"><template slot-scope="s"><el-button v-hasPermi="['order:exchange:query']" type="text" @click="open(s.row.id)">详情</el-button><el-button v-if="embedded" type="text" :disabled="!s.row.platform_tid" @click="$emit('related',s.row)">原单关联</el-button><el-button v-if="!s.row.business_exchange_id && s.row.conversion_state!=='SKIPPED'" v-hasPermi="['order:exchange:review']" type="text" :loading="busy===s.row.id" @click="convert(s.row)">{{ s.row.conversion_state==='FAILED'?'重试转单':'转单' }}</el-button></template></el-table-column>
    </el-table>
    <pagination v-show="total>0" :total="total" :page.sync="query.pageNum" :limit.sync="query.pageSize" @pagination="load" />
    <platform-exchange-detail ref="detail" @changed="load" />
  </div>
</template>
<script>
import { platformExchangeList, platformExchangeConvert } from '@/api/order/platformExchange'
import { exchangeCatalog } from '@/api/order/exchange'
import PlatformExchangeDetail from './PlatformExchangeDetail'
import MessageProgress from '@/views/oms/messaging/MessageProgress'
import { platformDocumentList } from '@/api/order/platformDocuments'
import { platforms, states } from './exchangeLabels'
import { conversionStates, sourceStates, phases, deadline } from './platformExchangeLabels'
const defaults=()=>({number:'',channelId:'',state:'',platformStatus:'',phase:'',sourceState:'',speed:'',pageNum:1,pageSize:20})
export default { name:'PlatformExchanges',props:{embedded:Boolean,sharedFilters:{type:Object,default:()=>({})},shopOptions:{type:Array,default:()=>[]},recordId:{type:Number,default:0}}, components:{PlatformExchangeDetail,MessageProgress}, data:()=>({query:defaults(),range:[],rows:[],total:0,channels:[],more:false,loading:false,sequence:0,busy:null,platforms,states,conversionStates,sourceStates,phases}),watch:{'$route.query.id'(id){if(!this.embedded&&id)this.open(Number(id))},sharedFilters(){if(this.embedded){this.query.pageNum=1;this.load()}},recordId(id){if(this.embedded&&id)this.open(id)}},async created(){this.channels=this.embedded?this.shopOptions:(await exchangeCatalog()).data.channels;this.query.number=this.$route.query.number||'';await this.load();if(this.embedded){if(this.recordId)this.open(this.recordId)}else if(this.$route.query.id)this.open(Number(this.$route.query.id))},methods:{deadline,shop(id){const c=this.channels.find(c=>Number(c.channel_id)===Number(id));return c?c.channel_name:`渠道 ${id}`},businessLink(r){return{path:'/oms-order/exchanges',query:{exchangeId:r.business_exchange_id}}},async load(){const seq=++this.sequence;this.loading=true;try{const params={...this.query,from:(this.range||[])[0],to:(this.range||[])[1],...(this.embedded?this.sharedFilters:{})};const r=(await(this.embedded?platformDocumentList('EXCHANGE',params):platformExchangeList(params))).data;if(seq===this.sequence){this.rows=r.rows;this.total=Number(r.total)}}finally{if(seq===this.sequence)this.loading=false}},search(){this.query.pageNum=1;this.load()},reset(){this.query=defaults();this.range=[];this.load()},open(id){this.$refs.detail.open(id)},async convert(r){if(this.busy)return;this.busy=r.id;try{const result=(await platformExchangeConvert(r.id)).data;this.$message[['SUCCESS','PENDING'].includes(result.state)?'success':'warning'](result.state==='SUCCESS'?'已关联业务换货单，等待业务处理':result.message||'平台申请无需转单');await this.load()}finally{this.busy=null}},backfill(){this.$router.push({path:'/oms-order/syncTasks',query:{kind:'EXCHANGE',action:'backfill',...((this.embedded?this.sharedFilters.channelId:this.query.channelId)?{channelId:this.embedded?this.sharedFilters.channelId:this.query.channelId}:{})}})},tasks(){this.$router.push({path:'/oms-order/syncTasks',query:{kind:'EXCHANGE',tab:'tasks'}})}} }
</script>
<style scoped>.hint{color:#8290a4;font-size:12px;line-height:1.8}.toolbar{display:flex;justify-content:space-between;align-items:center;gap:16px;margin:12px 0 20px}.target{margin:4px 0;color:#34445e}.warning{color:#b77515;line-height:1.7;overflow-wrap:anywhere}.el-table .el-button{white-space:normal;overflow-wrap:anywhere;text-align:left}</style>
